#include <stddef.h>
#include <stdint.h>
enum { LAB_FIELD_COUNT = 4 };
typedef struct { uint64_t value[LAB_FIELD_COUNT]; } LabResult;
_Static_assert(sizeof(LabResult) == LAB_FIELD_COUNT * sizeof(uint64_t), "Eight-byte field layout required");
extern const char *const lab_field_names[LAB_FIELD_COUNT];
void lab_operation(uint64_t initial, uint64_t incoming, LabResult *output);
void lab_model(uint64_t initial, uint64_t incoming, LabResult *output);
void abi_probe(void (*routine)(uint64_t, uint64_t, LabResult *), uint64_t initial, uint64_t incoming, LabResult *output, int *preserved);
#endif

#include "lab.h"
#include <inttypes.h>
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc > 2 || (argc == 2 && strcmp(argv[1], "--changed"))) {
        fputs("Use no argument or --changed.\n", stderr);
        return 64;
    }
    const int changed = argc == 2;
    const uint64_t initial = changed ? UINT64_C(0xffeeddccbbaa0099) : UINT64_C(0x1122334455667788);
    const uint64_t incoming = changed ? UINT64_C(0x123456788000807f) : UINT64_C(0xaabbccddeeff80ff);
    LabResult actual = {0}, expected = {0};
    lab_model(initial, incoming, &expected);
    lab_operation(initial, incoming, &actual);
    for (size_t field = 0; field < LAB_FIELD_COUNT; ++field) {
        if (actual.value[field] != expected.value[field]) {
            fprintf(stderr, "Incomplete width contract: field=%zu actual=%016" PRIx64 " expected=%016" PRIx64 "\n", field, actual.value[field], expected.value[field]);
            return 78;
        }
    }
    printf("initial=%016" PRIx64 " incoming=%016" PRIx64 "\n", initial, incoming);
    for (size_t field = 0; field < LAB_FIELD_COUNT; ++field)
        printf("%s=%016" PRIx64 "\n", lab_field_names[field], actual.value[field]);
    return 0;
}

#include "lab.h"
const char *const lab_field_names[LAB_FIELD_COUNT] = {"byte", "word", "dword", "qword"};
void lab_model(uint64_t initial, uint64_t incoming, LabResult *output) {
    output->value[0] = (initial & ~UINT64_C(0xff)) | (incoming & UINT64_C(0xff));
    output->value[1] = (initial & ~UINT64_C(0xffff)) | (incoming & UINT64_C(0xffff));
    output->value[2] = incoming & UINT64_C(0xffffffff);
    output->value[3] = incoming;
}

#include "lab.h"
#include <inttypes.h>
#include <stdio.h>

static int check(uint64_t initial, uint64_t incoming, size_t index) {
    LabResult actual = {0}, expected = {0};
    int preserved = 0;
    lab_model(initial, incoming, &expected);
    abi_probe(lab_operation, initial, incoming, &actual, &preserved);
    for (size_t field = 0; field < LAB_FIELD_COUNT; ++field) {
        if (!preserved || actual.value[field] != expected.value[field]) {
            fprintf(stderr, "case=%zu field=%zu actual=%016" PRIx64 " expected=%016" PRIx64 " preserved=%d\n", index, field, actual.value[field], expected.value[field], preserved);
            return 0;
        }
    }
    return 1;
}

int main(void) {
    const uint64_t fixed[] = {0, 1, 0x7f, 0x80, 0xff, 0x7fff, 0x8000, 0xffff,
        0x7fffffff, 0x80000000, 0xffffffff, UINT64_C(0x100000000),
        UINT64_C(0x1122334455667788), UINT64_C(0xaabbccddeeff80ff),
        UINT64_C(0xaaaaaaaaaaaaaaaa), UINT64_MAX};
    size_t cases = 0;
    for (size_t i = 0; i < sizeof fixed / sizeof fixed[0]; ++i)
        for (size_t j = 0; j < sizeof fixed / sizeof fixed[0]; ++j) {
            if (!check(fixed[i], fixed[j], cases)) return 1;
            ++cases;
        }
    uint64_t state = UINT64_C(0x41c64e6d12345678);
    for (size_t i = 0; i < 10013; ++i) {
        state = state * UINT64_C(6364136223846793005) + UINT64_C(1442695040888963407);
        const uint64_t initial = state;
        state = state * UINT64_C(6364136223846793005) + UINT64_C(1442695040888963407);
        if (!check(initial, state, cases)) return 1;
        ++cases;
    }
    printf("%zu independent width cases; %u fields; six preserved registers accepted\n", cases, (unsigned)LAB_FIELD_COUNT);
    return 0;
}

